 try{localStorage.setItem("potbreaker-locale",locale)}catch{}
 document.documentElement.lang=locale;
 const localePath=locale==="ko"?"/":"/"+locale;
 const ginkgoLink=document.getElementById("openGinkgo");if(ginkgoLink)ginkgoLink.href=locale==="ko"?"/ginkgo":"/ginkgo/"+locale;
 const potModeLink=document.getElementById("pb-mode-pot"),ginkgoModeLink=document.getElementById("pb-mode-ginkgo");
 if(potModeLink){potModeLink.href=locale==="ko"?"/":"/"+locale;if(!location.pathname.startsWith("/ginkgo"))potModeLink.setAttribute("aria-current","page");else potModeLink.removeAttribute("aria-current")}
 if(ginkgoModeLink){ginkgoModeLink.href=locale==="ko"?"/ginkgo":"/ginkgo/"+locale;if(location.pathname.startsWith("/ginkgo"))ginkgoModeLink.setAttribute("aria-current","page");else ginkgoModeLink.removeAttribute("aria-current")}
 document.querySelectorAll('a[href="/about"]').forEach(a=>a.href=locale==="ko"?"/about":"/"+locale+"/about");
 document.querySelectorAll('a[href="/privacy"]').forEach(a=>a.href=locale==="ko"?"/privacy":"/"+locale+"/privacy");
 if(location.pathname!==localePath)history.replaceState(null,"",localePath+location.search+location.hash);
 const canonical=document.querySelector('link[rel="canonical"]');if(canonical)canonical.href=location.origin+localePath;
